def f(L: int, Q: int, S: str, strs: List[str]) -> bool:
    binary_index = [0] * (1 << L)

    trans = ""
    for i in range(len(S)):
        count = bin(S[i]).replace("0b", "")
        trans = trans + (2 - len(count)) * "0" + count

    str_list = ["0" * L, "1" * L]
    for i in range(L+1, len(strs)):
        str_list.append(strs[i])

    return binarymiddleware(binary_index, trans, L, str_list)

def binarymiddleware(binary_index, trans: str, L: int, str_list: List[str]):
    for i in range(len(str_list)):
        binary_index[int(strs[i], 2)] |= 1 << i

    final_binary_string = ""
    fliped = [0] * (1 << L)
    for i in range(L):
        temp_binary = ""
        for j in range(1 << L):
            fliped[j] = (fliped[j] << 1) | binary_index[(j << (L-1-i)) & ((1 << L) - 1)]
            if fliped[j] & 1 << i:
                temp_binary = "1" + temp_binary
            else:
                temp_binary = "0" + temp_binary
        if temp_binary!= trans:
            return False

    return True
